mapper.select:
SELECT n.id, n.type, n.post_id AS postId, n.comment_id AS commentId, n.content,
       n.is_read AS `read`, n.created_at AS createdAt,
       u.id AS actorId, u.nickname AS actorNickname, u.avatar AS actorAvatar
FROM notifications n JOIN users u ON u.id = n.actor_id
WHERE n.recipient_id = #{recipientId}
ORDER BY n.created_at DESC LIMIT #{limit} OFFSET #{offset}
